def gcd(a, b):
    """Arrr! Return the greatest common divisor of two non‑negative integers."""
    # If one of the numbers be zero, the other be the answer, savvy?
    if b == 0:
        return a
    if a == 0:
        return b

    # Euclid's trusty method – keep subtractin' the smaller from the larger.
    while b != 0:
        a, b = b, a % b
    return a
